INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `status`, `popular`, `image`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`) VALUES
(1, 'T-Shirts', 't-shirts', 'Elevate your everyday style with our diverse T-shirt collection at StylishYou.', 0, 1, '1700075781.jpg', 'T-Shirts', 'Elevate your everyday style with our diverse T-shirt collection at StylishYou.', 't-shirts', '2023-11-15 19:16:21'),
(10, 'Pants', 'pants', 'Elevate your everyday style with our diverse Pants collection at StylishYou.', 0, 1, '1700769323.jpg', 'Pants', 'pants', 'pants, trousers', '2023-11-22 17:43:03'),
(13, 'Dresses', 'dresses', 'Women\'s Dresses: Effortless Elegance\r\nStep into sophistication with our curated collection of women\'s dresses. From casual chic to formal flair, find the perfect style for any occasion. Embrace timeless beauty and make a statement with every step. Explore now for a touch of elegance in every dress.', 0, 1, '1703117463.jpg', 'Women Dresses', 'Explore our chic collection of women\'s dresses, offering timeless elegance for every occasion. From casual styles to formal flair, discover effortless fashion that makes a statement. Shop now for a touch of sophistication and elevate your wardrobe.', 'women\'s dresses, fashion, style, elegant dresses, occasion wear, casual dresses, formal attire, trendy fashion,  wardrobe-essentials.', '2023-12-21 00:11:03'),
(14, 'Jackets', 'jackets', 'Our jackets are high-quality materials, durability, and performance in various outdoor activities. They are designed to protect from the elements, such as wind, rain, and cold temperatures, making them popular among outdoor enthusiasts and adventurers.', 0, 1, '1703501980.webp', 'Jackets', 'Explore the latest trends in our jackets collection. From timeless classics to contemporary styles, find the perfect outerwear for any occasion. Elevate your wardrobe with our high-quality jackets at StylishYou.', 'jackets, outerwear, winter fashion, stylish coats, trendy jackets, North Face jackets, cold weather apparel, fashion trends, men\'s jackets, women\'s jackets', '2023-12-25 10:58:46'),
(15, 'Shorts', 'shorts', 'StylishYou Shorts: Elevate your look with our chic and comfortable shorts. From classic to trendy styles, our collection blends fashion and ease seamlessly. Explore your style with StylishYou.', 0, 1, '1703700133.jpg', 'Shorts', 'StylishYou Shorts: Discover fashion-forward comfort with our chic shorts collection. From classic to trendy styles, elevate your look effortlessly. Explore StylishYou for the perfect blend of style and ease.', 'Stylish shorts, Trendy fashion, Comfortable clothing, Chic apparel, Fashion-forward styles, Casual elegance, Modern wardrobe, Versatile shorts, StylishYou collection, Contemporary fashion', '2023-12-27 18:02:13'),
(16, 'Skirts', 'skirts', '**Category Description: Women\'s Skirts**\r\n\r\n*Explore a World of Feminine Elegance:*\r\n\r\nWelcome to the enchanting realm of women\'s skirts, where style meets versatility in a dance of fabrics, cuts, and designs. Skirts have been a timeless staple in women\'s fashion, offering a diverse range of options suitable for various occasions and personal tastes.\r\n\r\n**1. A Symphony of Styles:**\r\n   - *A-line:* Graceful and universally flattering, A-line skirts flow gently from the waist, creating an elegant silhouette.\r\n   - *Pencil:* Tailored and chic, pencil skirts hug the body\'s curves, exuding a sophisticated and professional vibe.\r\n   - *Maxi:* Embrace bohemian charm with flowing, ankle-length maxi skirts, perfect for both casual and formal settings.\r\n   - *Mini:* Bold and playful, mini skirts add a youthful and energetic flair to any ensemble.\r\n\r\n**2. Fabric Fantasia:**\r\n   - *Cotton:* Light and breathable, cotton skirts are ideal for warm days, providing comfort and a casual aesthetic.\r\n   - *Denim:* The timeless appeal of denim skirts adds a touch of Americana to your wardrobe, suitable for casual outings.\r\n   - *Silk:* Luxurious and smooth, silk skirts elevate your look with a touch of opulence, perfect for special occasions.\r\n   - *Leather:* Edgy and bold, leather skirts make a statement, exuding confidence and contemporary flair.\r\n\r\n**3. Patterns and Prints:**\r\n   - *Floral:* Embrace the beauty of nature with floral-print skirts, radiating a sense of freshness and femininity.\r\n   - *Stripes:* Classic and versatile, striped skirts offer a timeless pattern suitable for both casual and formal settings.\r\n   - *Polka Dot:* Playful and retro, polka dot skirts add a whimsical touch to your ensemble, perfect for a vintage-inspired look.\r\n   - *Abstract:* For the avant-garde fashionista, abstract patterns bring an artistic and modern edge to skirt designs.\r\n\r\n**4. Occasion-Ready Ensembles:**\r\n   - *Casual Comfort:* Enjoy laid-back vibes with breezy skirts paired with a simple tee or a casual blouse for a relaxed day out.\r\n   - *Office Chic:* Elevate your work wardrobe with tailored pencil skirts, offering a polished and professional appearance.\r\n   - *Evening Glam:* Step into the spotlight with maxi or mini skirts adorned with sequins or metallic details, perfect for a night out.\r\n\r\n**5. Embracing Trends:**\r\n   - *Asymmetry:* Play with unconventional hemlines and asymmetric cuts for a contemporary and avant-garde look.\r\n   - *Ruffles:* Channel a romantic aesthetic with skirts adorned with cascading ruffles, adding movement and charm.\r\n\r\nWhether you\'re seeking casual comfort, professional sophistication, or evening glamour, women\'s skirts provide a canvas for expressing your unique style, inviting you to twirl through life with confidence and grace.', 0, 1, '1703778004.webp', 'Skirts', 'Elevate your style with our curated collection of women\'s skirts, featuring a harmonious blend of timeless designs and contemporary trends. From versatile A-line and pencil skirts to playful minis and elegant maxis, our selection caters to every occasion. Dive into a world of fabrics, patterns, and prints, and embrace the perfect skirt to express your unique personality. Explore the intersection of comfort and chic, and redefine your wardrobe with skirts that effortlessly transition from casual to formal. Step into a realm of feminine grace and discover the perfect skirt for every chapter of your life.', 'women\'s skirts, A-line skirts, Pencil skirts, Maxi skirts, Mini skirts, Casual skirts, Formal skirts, Trendy skirts, Fashion skirts, Skirt styles, Floral skirts, Denim skirts, Silk skirts, Leather skirts, Skirt patterns, Office skirts, Evening skirts, Fashion trends, Skirt outfits, Seasonal skirts.', '2023-12-28 15:40:04'),
(19, 'Accessories', 'accessories', 'Explore our diverse collection of accessories, designed to complement every aspect of your style. From statement-making watches to sleek leather wallets, our Accessories category is your one-stop destination for elevating your look. Discover timeless pieces crafted from premium materials, offering both functionality and fashion-forward design. Whether you\'re searching for the perfect tie to complete your formal ensemble or a versatile bag to carry your essentials, our curated selection ensures you\'ll find the finishing touches to suit any occasion. Shop now and add a touch of sophistication and personality to your wardrobe with our range of must-have accessories.', 0, 1, '1710018241.png', 'Accessories', 'Discover a curated selection of men\'s accessories at our online store. From stylish watches and premium leather wallets to versatile bags and statement-making ties, find the perfect finishing touches to elevate your look. Explore our collection now and add sophistication and personality to your wardrobe.', 'Men\'s accessories, Women\'s accessories, Fashion accessories, Watches, Wallets, Bags, Ties, Belts, Sunglasses, Hats, Cufflinks, Bracelets, Scarves, Gloves, Keychains, Rolex, Gucci, Prada, Louis Vuitton, Montblanc, Hermès, Cartier, Burberry, Ray-Ban, Fendi\r\n\r\n\r\n\r\n\r\n', '2024-03-09 21:04:01');

