INSERT INTO `products` (`id`, `category_id`, `name`, `gender`, `slug`, `brand`, `rate`, `small_description`, `description`, `original_price`, `selling_price`, `image`, `image2`, `image3`, `qty`, `status`, `trending`, `meta_title`, `meta_keywords`, `meta_description`, `created_at`) VALUES
(1, 1, 'Men Random Bird & Floral Print Shirt', 'Men', 'men-random-bird-floral-print-shirt', 'SHEIN', 5, 'Elevate your style with the Manfinity Men Random Bird & Floral Print Shirt, a fashion-forward statement piece. This shirt seamlessly combines a playful mix of random bird and floral prints, offering a unique and vibrant look that effortlessly blends sophistication with casual charm.', 'Color:	Multicolor\r\nStyle:	Boho\r\nPattern Type:	Floral, Random Print\r\nType:	Shirt\r\nNeckline:	Collar\r\nSleeve Length:	Short Sleeve\r\nDetails:	Button Front\r\nSleeve Type:	Regular Sleeve\r\nLength:	Regular\r\nFit Type:	Regular Fit\r\nFabric:	Non-Stretch\r\nMaterial:	Fabric\r\nComposition:	98% Polyester, 2% Elastane\r\nCare Instructions:	Machine wash, do not dry clean,wash with the soft detergent\r\nSheer:	No', 48.05, 34.28, '1706106840.jpg', '1709311282_2.webp', '1711039443_3.webp', 15, 0, 1, 'Summer Collection 2023 : Men Random Bird & Floral Print Shirt - StylishYou', 'Boho shirt, Floral print, Bird pattern, Multicolor fashion, Collar shirt, Short sleeve, Button-front details, Regular fit, Non-stretch fabric, Polyester, Comfortable attire, Machine washable, Versatile styling, Men\'s casual wear.', 'Discover boho elegance with our Manfinity Men\'s Multicolor Bird & Floral Print Shirt. This regular-fit, non-stretch fabric shirt blends floral and random prints for a unique style, featuring a collar, short sleeves, and easy machine-wash care.', '2023-12-19 00:28:10'),
(2, 13, 'SLEEVELESS DRAPED MIDI DRESS', 'Women', 'sleeveless draped midi dress', 'ZARA', 4, 'Sleeveless dress in knit fabric with a high neck. Draped fabric. Matching lining. Back slit at the hem. Invisible back zip fastening.', 'With a range of ornate dresses, two-piece sets and chic separates to mix and match, the brand offers style-savvy women the perfect combination of sultry sophistication and luxurious quality. \r\n\r\n- Woven fabrication; some stretch\r\n- Asymmetrical round neckline\r\n- Sleeveless\r\n- Body-hugging\r\n- Midi length\r\n\r\nOUTER SHELL\r\n100% polyester\r\n\r\nLINING\r\n100% polyester\r\nWhich contains at least:\r\nOUTER SHELL: 100% RCS certified recycled polyester\r\n\r\nClothing Care Guide\r\n- Machine wash at max. 30ºC/86ºF with short spin cycle\r\n- Do not use bleach\r\n- Iron at a maximum of 110ºC/230ºF\r\n- Dry clean with tetrachloroethylene\r\n- Do not tumble dry', 165, 45, '1703175084.jpg', '1710016290_2.jpg', '1710016290_3.jpg', 25, 0, 1, 'Summer Sleeveless Draped Midi Dresses for Effortless Style', 'sleeveless dresses, draped midi dress, women\'s fashion, elegant style, occasion wear, wardrobe-essentials.', 'Elevate your style with our Sleeveless Draped Midi Dresses. Discover timeless elegance and effortless charm in every step. Perfect for any occasion, shop now for a sophisticated wardrobe upgrade.', '2023-12-21 00:26:43'),
(5, 1, 'Plain Striola Shirt', 'Men', 'short-sleeve button-down', 'SHEIN', 4.5, 'this short-sleeve button-down can take you anywhere without missing a beat. Made in a lighter-weight cotton knit, this shirt features a vintage-inspired camp collar and heritage patterns that will never go out of style. By buying cotton products from J.Crew, you\'re supporting our investment in Better Cotton\'s mission to help cotton communities survive and thrive while protecting and restoring the environment. This product is sourced through a system of mass balance and therefore may not contain Better Cotton.', 'Color: green, beige\r\nCut: plain\r\nSleeve: short sleeve\r\nLength: short\r\nPattern style: printed\r\nDetails: button down\r\nMaterial: satin\r\nGender: men & women\r\nOccasion: casual', 56, 35, '1703263636.jpg', '1709412264_2.webp', '1711536645_3.webp', 10, 0, 1, 'Summer Collection 2023 : Men Plain Striola Shirt - StylishYou', 'Short-sleeve shirt\r\nButton-down\r\nCotton knit\r\nCamp collar\r\nHeritage patterns\r\nVintage-inspired\r\nJ.Crew\r\nBetter Cotton\r\nSustainable fashion\r\nCasual style', 'Discover versatile style with our Short-Sleeve Button-Down Shirt. Crafted from a lightweight cotton knit, this shirt is your go-to for any occasion, boasting a vintage-inspired camp collar and timeless heritage patterns. With J.Crew, your purchase supports Better Cotton\'s mission to empower cotton communities and promote environmental sustainability. Please note, this product is sourced through a mass balance system and may not contain Better Cotton directly. Elevate your wardrobe while making a positive impact.', '2023-12-22 16:47:16'),
(6, 13, 'Linen Blend Printed Midi Dress', 'Women', 'linen blend printed midi dress', 'ZARA', 4, 'Dress made of linen blend fabric. Elastic straight neckline with wide straps. Front slit at hem. Side hidden in-seam zip closure.', 'COMPOSITION & CARE\r\n\r\nCOMPOSITION\r\nWe work with monitoring programs to guarantee compliance with the social, environmental, and health and safety standards of our products. To assess its compliance, we have developed an audit program and plans for continual improvement.\r\n\r\nOUTER SHELL\r\n80% viscose\r\n20% linen\r\n\r\nCARE\r\nCaring for your clothes is caring for the environment.\r\nLower temperature washes and delicate spin cycles are gentler on garment, helping to maintain the color, shape and structure of the fabric. At the same time it reduces energy consumption that is used in care processes. \r\n\r\nMachine wash max. 30ºC/86ºF delicate cycle\r\n\r\n- Do not use bleach / whitener\r\n- Iron maximum 110ºC/230ºF\r\n- Do not dry clean\r\n- Do not tumble dry', 59.9, 35.99, '1703499074.jpg', '1709413687_2.jpg', '1709413578_3.webp', 15, 0, 1, 'Summer Collection 2023 : Linen Blend Printed Midi Dress - StylishYou', 'Linen Blend, Printed Dress, Midi Dress, Fashion, Stylish Apparel, Women\'s Clothing, Elegant Attire.', 'Discover elegance with our Linen Blend Printed Midi Dress. Perfect for any occasion, this stylish dress combines comfort and sophistication. Explore our collection at StylishYou for the latest in fashion.', '2023-12-25 10:11:14'),
(7, 13, 'Floral Print Ruffled Dress', 'Women', 'floral print ruffled dress', 'ZARA', 4.5, 'V-neck midi dress with ruffled wide elastic straps. Front slit at hem. Ruffled trim.', 'COMPOSITION & CARE\r\n\r\nCOMPOSITION\r\nWe work with monitoring programs to guarantee compliance with the social, environmental, and health and safety standards of our products. To assess its compliance, we have developed an audit program and plans for continual improvement.\r\n\r\nOUTER SHELL\r\n100% polyester\r\nLINING\r\n100% polyester\r\n\r\nWhich has at least:\r\nOUTER SHELL: 50% RCS-certified recycled polyester\r\nCERTIFIED MATERIALS\r\nRCS CERTIFIED RECYCLED POLYESTER\r\n\r\nNowadays, recycled polyester is mainly made from PET plastic waste. This is a type of plastic that is widely used in a variety of items, such as plastic bottles. Using recycled materials helps limit the production of virgin polyester fiber. It is certified to the Recycled Content Standard (RCS), which verifies the recycled content and tracks it from source to final product.\r\nCertified by Intertek 193341\r\n\r\nCARE\r\nCaring for your clothes is caring for the environment.\r\nLower temperature washes and delicate spin cycles are gentler on garment, helping to maintain the color, shape and structure of the fabric. At the same time it reduces energy consumption that is used in care processes. \r\n\r\nClothing care guide\r\n- Machine wash max. 30ºC/86ºF delicate cycle\r\n- Do not use bleach / whitener\r\n- Iron maximum 110ºC/230ºF\r\n- Tetrachloroethylene Dry Clean\r\n- Do not tumble dry', 69.9, 45.99, '1703499556.jpg', '1709413876_2.jpg', '1709413876_3.jpg', 10, 0, 1, 'Summer Collection 2023 : Floral Print Ruffled Dress - StylishYou', 'floral dress, ruffled dress, chic fashion, summer style, women\'s clothing, stylish attire.', 'Step into summer with elegance in our Floral Print Ruffled Dress. Embrace the timeless beauty of floral prints combined with playful ruffled details. Explore chic summer fashion at StylishYou.', '2023-12-25 10:19:16'),
(8, 14, 'Men Motorcycle Sports Jacket', 'Men', ' men-motorcycle-sports-jacket', 'THE NORTH FACE', 5, 'Built for mountain and city-life, the iconic 1996 Retro Nuptse Jacket has an unmistakable silhouette, and with its oversized down baffles, stowable hood, and classic ripstop fabric, you\'ll stay warm when the weather gets cold.\r\n- Relaxed fit with a boxy silhouette\r\n- Inspired by the iconic design lines of our 1996 Nuptse Jacket\r\n- Original shiny ripstop fabric for durability\r\n- Non-PFC DWR finish for added protection\r\n- 700 fill goose down offers warmth yet remains extremely compressible\r\n- Oversize baffles\r\n- Attached, stowable, three-piece hood packs into stand collar\r\n- Exposed VISLON® center front zip\r\n- Secure-zip hand pockets\r\n- Jacket stows in the right-hand pocket\r\n- Encased-elastic cuffs with adjustable hook-and-loop cuff tabs and Triclimate® loops for snap-in compatibility\r\n- Shockcord at hem for adjustability\r\n- Logo on the left chest and back-right shoulder', 'COLLECTION : Winter 2024\r\n\r\nACTIVITY : Lifestyle\r\n\r\nTECHNOLOGY : Goose Down\r\n\r\nGENDER : Men\r\n\r\nMATERIAL :\r\n body : 40D 54 g/m² 100% recycled nylon ripstop with non-PFC durable water-repellent (non-PFC DWR) finish / collar and yoke: 50D 69 g/m² 100% recycled nylon taffeta with non-PFC DWR finish / lining: 50D 69 g/m² 100% recycled nylon taffeta with non-PFC DWR finish / insulation: 700 fill goose down; certified to the Responsible Down Standard (RDS) by Control Union.\r\n\r\nAVERAGE WEIGHT :  775 g (1 lb 11.34 oz)\r\n\r\nCENTRE BACK LENGTH : 26\"', 380, 369.99, '1704925593.webp', '1710017061_2.webp', '1710017061_3.webp', 17, 0, 1, 'Winter Collection 2024 : Men’s ’92 Reversible Nuptse Jacket - StylishYou', 'Men’s ’92 Reversible Nuptse Jacket, Reversible Nuptse Jacket, Men\'s Outerwear, Fashion, Winter Jacket, Outdoor Apparel, ’92 Collection, Stylish Jackets, THE NORTH FACE, StylishYou.', 'Discover the Men Motorcycle Sports Jacket, a perfect blend of style and functionality. Engineered for motorcycle enthusiasts, this jacket offers premium protection and a sleek design. Explore now!', '2023-12-25 11:05:36'),
(9, 14, 'Men’s Build Up Jacket', 'Men', 'mens-build-up-jacket', 'THE NORTH FACE', 4.5, 'Waterproof, breathable and made from 100% recycled fabrics, the sustainably-conscious Men’s Build Up Jacket is slope-ready and street-approved. With an integrated powder skirt, helmet-compatible hood and secure-zip hand pockets, this jacket is designed for everyone.', 'Style : NF0A82VM\r\nSolid Body  : 70D 111 g/m² DryVent™ 2L—100% recycled nylon with non-PFC durable water-repellent (non-PFC DWR) finish\r\nPrint Body : 75D 119 g/m² DryVent™ 2L—100% recycled polyester with non-PFC DWR finish\r\nLining : 50 g/m² 100% recycled polyester mesh\r\nSizes : XXS, XS, S, M, L, XL, XXL, 3XL\r\nAvg Weight : 521 g (1 lb 2.38 oz)\r\nCenter Back : 29.25\'\'\r\nLining : 50 g/m² 100% recycled polyester mesh\r\nPrint Body : 75D 119 g/m² DryVent™ 2L—100% recycled polyester with non-PFC DWR finish', 200, 160, '1703512669.jpg', '1710016832_2.avif', '1710016832_3.webp', 40, 0, 1, 'Winter Collection 2024 : Men’s Build Up Jacket - StylishYou', 'Men’s Build Up Jacket, The North Face, Winter Collection, Winter Fashion, Outdoor Apparel, Men\'s Jackets.', 'Discover the latest addition to our Winter Collection 2024 – the Men’s Build Up Jacket from The North Face. Embrace warmth, style, and durability with this iconic winter essential. Explore the best in outdoor fashion now.', '2023-12-25 13:57:49'),
(10, 14, 'Women’s Plus Freedom Stretch Jacket', 'Women', 'womens-plus-freedom-stretch-jacket', 'THE NORTH FACE', 5, 'As a new addition to our fan-favourite Freedom line, the slim-fit Women’s Plus Freedom Stretch Jacket—available in extended sizing— delivers waterproof coverage and the on-mountain features you need for skiing, riding or touring. The shell and lining fabric are both made with elastane to provide a greater range of motion for comfort and performance on the slopes.', 'Style:  NF0A7WYR\r\nBody : 90D x 70D 130 g/m² DryVent™ 2L—96% recycled nylon, 4% elastane with non-PFC durable water-repellent (non-PFC DWR) finish\r\nFront-Body Lining : 75D 66 g/m² 100% recycled polyester taffeta\r\nBack And Sleeve Lining : 20D x 30D 70 g/m² 91% nylon, 9% elastane with non-PFC DWR finish\r\nSizes : 1X, 2X, 3X\r\nAvg Weight : 774 g (1 lb 11.3 oz)\r\nCenter Back : 31\'\'', 375, 75, '1703514877.jpeg', '1710017394_2.webp', '1710017394_3.webp', 15, 0, 1, 'Winter Collection 2024 : Women’s Plus Freedom Stretch Jacket -  StylishYou', 'Women’s Plus Freedom Stretch Jacket, Winter Collection 2024, Women\'s Fashion, Winter Jacket, Outdoor Apparel, StylishYou.', 'Introducing our Women’s Plus Freedom Stretch Jacket – a perfect blend of style and comfort for the Winter Collection 2024. Explore freedom of movement and fashion-forward design with this essential winter jacket for women. Shop now for the latest in winter fashion.', '2023-12-25 14:06:54'),
(11, 14, 'BOUCLÉ OVERSIZE BOMBER JACKET', 'Women', 'boucle-oversize-bomber-jacket', 'ZARA', 4.5, 'Oversize bomber jacket featuring a round neck and long sleeves. Front pockets. Elasticated hem. Front metal zip fastening.', 'COMPOSITION, CARE & ORIGIN\r\n\r\nCOMPOSITION\r\nWe work with monitoring programmes to ensure compliance with our social, environmental and health and safety standards for our products. To assess compliance, we have developed a programme of audits and continuous improvement plans.\r\n\r\nOUTER SHELL\r\n100% polyester\r\n\r\nCARE\r\nCaring for your clothes is caring for the environment.\r\nTo keep your jackets and coats clean, you only need to freshen them up and go over them with a cloth or a clothes brush. This process is more gentle on fabrics and also reduces water and energy consumption when washing. \r\n\r\nClothing Care Guide\r\n- Machine wash at max. 30ºC/86ºF with short spin cycle\r\n- Do not use bleach\r\n- Iron at a maximum of 110ºC/230ºF\r\n- Dry clean with tetrachloroethylene\r\n- Do not tumble dry\r\n- Iron inside out\r\n\r\nORIGIN\r\nWe work with our suppliers, workers, unions and international organisations to develop a supply chain in which human rights are respected and promoted, contributing to the United Nations Sustainable Development Goals. \r\n\r\nThanks to the collaboration with our suppliers, we work to know the facilities and processes used to manufacture our products in order to understand their traceability.\r\nMade in Cambodia.', 49.99, 15.99, '1703514114.jpg', '1710016571_2.jpg', '1710016571_3.jpg', 45, 0, 1, 'Winter Collection 2024 : BOUCLÉ OVERSIZE BOMBER JACKET - StylishYou', 'BOUCLÉ OVERSIZE BOMBER JACKET, Winter Collection 2024, Women\'s Fashion, Bomber Jacket, Winter Apparel, ZARA, StylishYou.', 'Discover the BOUCLÉ OVERSIZE BOMBER JACKET from our Winter Collection 2024. Embrace style and warmth with this oversized bomber jacket. Elevate your winter wardrobe with high-quality bouclé fabric. Shop now for the latest in winter fashion.', '2023-12-25 14:21:54'),
(12, 15, 'Comfort Bermuda Short', 'Men', 'comfort-bermuda-short', 'ZARA', 4, 'Bermuda shorts featuring an adjustable elasticated waistband with drawstrings. Front pleats. Front pockets and rear welt pockets. Turn-up hems.', 'COMPOSITION\r\nWe work with monitoring programmes to ensure compliance with our social, environmental, and health and safety standards for our products. To assess compliance, we have developed a programme of audits and continuous improvement plans.\r\nOUTER SHELL\r\n73% polyester\r\n23% viscose\r\n4% elastane\r\nCARE\r\nCaring for your clothes is caring for the environment.\r\nLower temperature washes and delicate spin cycles are gentler on garments and help protect the color, shape, and structure of the fabric. Furthermore, they reduce the amount of energy used in care processes.\r\n\r\nClothing Care Guide\r\nMachine wash at max. 30ºC/86ºF with a short spin cycle\r\nDo not use bleach\r\nIron at a maximum of 110ºC/230ºF\r\nDry clean with tetrachloroethylene\r\nDo not tumble dry\r\nORIGIN\r\nWe work with our suppliers, workers, unions, and international organizations to develop a supply chain in which human rights are respected and promoted, contributing to the United Nations Sustainable Development Goals.\r\n\r\nThanks to the collaboration with our suppliers, we work to know the facilities and processes used to manufacture our products to understand their traceability.\r\nMade in Turkey\r\n', 25.92, 12.99, '1703700454.jpg', '1709414091_2.jpg', '1709414091_3.jpg', 20, 0, 1, 'Summer Collection 2023 : Comfort Bermuda Short - StylishYou', 'StylishYou, ZARA, fashion, stylish clothing, trendy apparel, fashion trends, contemporary styles, clothing brand, sustainable fashion, modern wardrobe.', 'Explore our product\'s commitment to social, environmental, and safety standards. Our OUTER SHELL, crafted from 73% polyester, 23% viscose, and 4% elastane, exemplifies quality. Learn about our eco-friendly CARE practices, and discover the ORIGIN of our products—crafted with respect for human rights. Made in Turkey, our fashion tells a story of sustainability and responsibility.', '2023-12-27 18:07:34'),
(13, 16, 'Pleated Coated Skirt', 'Women', 'pleated-coated-skirt', 'H&M', 4.5, 'Calf-length circle skirt in pleated, coated jersey. Concealed zipper at one side with hook-and-eye fastening. Lined.', 'Model size: The model is 175cm/5\'9\" and wears a size S\r\nSize:\r\nWaist: Circumference: 83.0 cm (Size M), Back: Length: 82.0 cm (Size M)\r\nLength: Midi\r\nWaist Rise: Regular waist\r\nFit: Regular fit\r\nStyle: Circular\r\nDescription: Black, Solid-color\r\nImported: Yes\r\nConcept: H&M EDITION\r\n\r\nComposition\r\nPolyester 90%, Spandex 10%\r\nMaterial: Jersey\r\nMaterials in this product explained\r\nPolyester\r\nPolyester is a synthetic fiber made from crude oil (a fossil resource).\r\nSpandex\r\nElastane is an elastic synthetic fiber made from oil (a fossil resource).\r\n\r\nCare guide\r\nYou too can help the environment and make fashion more sustainable. Bring unwanted clothes or home textiles to any H&M store and they will be reworn, reused or recycled.\r\n\r\nCare instructions\r\n- Only non-chlorine bleach when needed\r\n- No dry clean\r\n- No iron\r\n- Machine wash cold\r\n- Line dry', 84.99, 42.48, '1703778317.jpeg', '1709414257_2.webp', '1709414257_3.jpeg', 18, 0, 1, 'Summer Collection 2023 : Pleated Coated Skirt - StylishYou', 'Calf-length circle skirt, Pleated coated jersey, Concealed zipper, Hook-and-eye fastening, Lined, StylishYou, H&M, Summer collection, Fashion, Style, Women\'s Clothing.', 'Discover elegance in motion with our calf-length circle skirt crafted from pleated, coated jersey. This stylish piece features a concealed zipper at one side with a secure hook-and-eye fastening, ensuring a seamless fit. The skirt is meticulously lined for added comfort and a flawless silhouette. Elevate your wardrobe with this versatile and chic addition, perfect for a sophisticated and fashion-forward look. Explore the fusion of texture and design in our pleated, coated jersey skirt – where every detail is tailored to perfection.', '2023-12-28 15:45:17'),
(14, 10, 'Regular Fit Ripstop Cargo Pants', 'Men', 'regular-fit-ripstop-cargo-pants', 'H&M', 4, 'Regular-fit cargo trousers in a hard-wearing ripstop weave. Covered elastication and a drawstring at the waist, and a zip fly and button. Side, back and leg pockets with a flap and concealed press-studs, and an elastic drawstring with a cord stopper at the hems.', 'Size:\r\nInside leg: Length : 76.75 cm (Size L)\r\nLength: Long\r\nWaist Rise: Regular waist\r\nFit: Regular fit\r\nStyle: Cargo\r\nDescription: Black, Solid colour\r\n\r\nComposition\r\nShell:Cotton 98%, Elastane 2%\r\nPocket lining:Cotton 100%\r\nAdditional material information\r\nThe total weight of this product contains:\r\n\r\n20% Recycled cotton\r\nWe exclude the weight of minor components such as, but not exclusively: threads, buttons, zippers, embellishments and prints.\r\n\r\nThe total weight of the product is calculated by adding the weight of all layers and main components together. Based on that, we calculate how much of that weight is made out by each material. For sets & multipacks all pieces are counted together as one product in calculations.\r\n\r\nMaterials in this product explained\r\nCotton\r\nCotton is a soft and versatile natural fibre harvested from the cotton plant.\r\nElastane\r\nElastane is an elastic synthetic fibre made from oil (a fossil resource).\r\nRecycled cotton\r\nRecycled cotton is cotton made from textile waste in production or from end-of-life textile waste. The waste is mechanically recycled and spun into new yarn.\r\n\r\nCare guide\r\nYou too can help the environment and make fashion more sustainable. Bring unwanted clothes or home textiles to any H&M store and they will be reworn, reused or recycled.\r\n\r\nCare instructions\r\n- Wash with similar colours\r\n- Medium iron\r\n- Only non-chlorine bleach when needed\r\n- Machine wash at 40°\r\n- Can be dry cleaned\r\n- Line dry', 67.48, 49.99, '1703802193.webp', '1710017245_2.jpeg', '1710017155_3.jpeg', 23, 0, 1, 'Winter Collection 2024 : Regular Fit Ripstop Cargo Pants - StylishYou', ' Regular Fit Ripstop Cargo Pants,\r\n  StylishYou,\r\n  H&M-inspired fashion,\r\n  Cargo Pants Collection,\r\n  Comfortable and Stylish Pants,\r\n  Trendy Wardrobe Essentials,\r\n  Men\'s Fashion Trends,\r\n  Utility Style Bottoms,\r\n  H&M-inspired Apparel,\r\n  Stylish and Functional Cargo Pants.', 'Explore our collection of Regular Fit Ripstop Cargo Pants at StylishYou. Discover the perfect blend of comfort and style, inspired by H&M\'s fashion trends. Elevate your wardrobe with these versatile and trendy cargo pants.', '2023-12-28 22:23:13'),
(18, 19, 'Double Box Chain Bracelet', 'Men', 'double box chain bracelet', 'David Yurman', 4, 'David Yurman chains are inspired by classical and original motifs, and are meticulously crafted by artisans. Each is designed to be worn alone, layered, or complemented with unique pendants or amulets from our other collections.', 'Sterling silver\r\nBracelet, 4mm\r\nLobster clasp\r\nStyle #BC0368MSS\r\n\r\nMetal Care :\r\nUse the white side of the provided David Yurman polishing cloth to gently wipe clean, then remove any remaining tarnish with mild diluted soap. Rinse with warm water and dry thoroughly before storing the design in its jewelry pouch.', 375, 131.25, '1710018628_1.webp', '1710018604_2.webp', '1710018604_3.webp', 25, 0, 1, 'David Yurman Collection 2024', 'David Yurman, chains, jewelry, accessories, craftsmanship, classical motifs, original motifs, artisans, pendants, amulets.', 'Discover David Yurman\'s exquisite chains, meticulously crafted by artisans, blending classical and original motifs. Versatile and elegant, these chains are designed to be worn alone or layered, offering endless styling possibilities. Explore our collection and elevate your look with unique pendants and amulets to create your signature style.', '2024-03-09 21:10:04'),
(19, 19, 'Memento Mori Skull Bracelet', 'Men', 'momento mori skull bracelet', 'DAVID YURMAN', 5, 'Inspired by Memento Mori—the Medieval practice of reflecting on one’s mortality—the symbol of the skull reminds us to live life to its fullest.', 'Details :\r\n18-karat yellow gold\r\nForged carbon\r\nBracelet, 6mm\r\nPush clasp\r\nStyle #B15716M88BFG\r\n\r\nMetal Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch. Do not use abrasive cleaners, steamers or ultrasonic machines.', 650, 499.99, '1710066365_1.webp', '1710066312_2.webp', '1710066312_3.webp', 18, 0, 1, 'Memento Mori Collection for Men', 'David Yurman, Memento Mori, skull symbol, mortality reflection, live life, symbolic jewelry.', 'Inspired by Memento Mori, the Medieval practice of reflecting on one’s mortality, our collection features skull symbols, urging us to live life to its fullest.', '2024-03-10 10:25:12'),
(20, 19, 'Pavéflex Bracelet', 'Women', 'pavéflex bracelet', 'DAVID YURMAN', 5, 'Through innovative engineering, this Pavéflex® design twists and moves with ease while never forgetting its elegant form. An opening in the back allows it to expand to fit a range of sizes.', 'Details :\r\n18-karat yellow gold\r\nPavé-set diamonds, 3.13 total carat weight\r\nBracelet, 7.5mm\r\nFlexible design\r\nThis item can be engraved. Please contact customer care for more information.\r\nStyle #B16852D88ADI\r\n\r\nMetal Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch. Do not use abrasive cleaners, steamers or ultrasonic machines.\r\n\r\nGemstone Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch.', 500, 449.99, '1710066852_1.webp', '1710066835_2.webp', '1710066835_3.webp', 10, 0, 1, 'Pavéflex Collection for Women', 'David yurman, pavéflex collection, innovative engineering, bracelet design, flexibility, elegant form, adaptable fit.', 'Experience the innovation of our Pavéflex® design, engineered for effortless movement and timeless elegance. With its adaptable opening, this bracelet ensures a comfortable fit for all sizes.', '2024-03-10 10:33:55'),
(21, 19, 'Pavéflex Bracelet Rose Gold ', 'Women', 'pavéflex bracelet rose gold', 'DAVID YURMAN', 4.5, 'Through innovative engineering, this Pavéflex® design twists and moves with ease while never forgetting its elegant form. An opening in the back allows it to expand to fit a range of sizes.', 'Details :\r\n18-karat rose gold\r\nPavé-set diamonds, 0.99 total carat weight\r\nBracelet, 3.5mm\r\nFlexible design\r\nStyle #B13221D8RADI\r\n\r\nMetal Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch. Do not use abrasive cleaners, steamers or ultrasonic machines.\r\n\r\nGemstone Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch.', 550, 499.99, '1710067200_1.webp', '1710067186_2.webp', '1710067186_3.webp', 10, 0, 1, 'Pavéflex Collection for Women', 'pavéflex bracelet, rose gold, david yurman, pavéflex collection, jewelry, sophistication, versatility.', 'Discover the allure of our Pavéflex Bracelet in rose gold, a symbol of sophistication and versatility. With its innovative design and timeless elegance, it\'s the perfect accessory for any occasion.', '2024-03-10 10:39:46'),
(22, 19, 'Memento Mori Skull Amulet Necklace', 'Men', 'memento mori skull amulet', 'DAVID YURMAN', 4.5, 'Inspired by Memento Mori—the Medieval practice of reflecting on one’s mortality—the symbol of the skull reminds us to live life to its fullest.', 'Details :\r\nAmulet only; chain not included. To complete the look, add a box chain.\r\n\r\nSterling silver\r\nPavé-set black diamonds, 0.05 total carat weight\r\nAmulet, 18 x 13.4mm\r\nTotal length, 29mm\r\nStyle #D25437MSSABD\r\nUPC 192740949821\r\n\r\nMetal Care :\r\nUse the white side of the provided David Yurman polishing cloth to gently wipe clean, then remove any remaining tarnish with mild diluted soap. Rinse with warm water and dry thoroughly before storing the design in its jewelry pouch.\r\n\r\nGemstone Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch.', 425, 385.99, '1710081186_1.webp', '1710081169_2.webp', '1710081169_3.webp', 28, 0, 1, 'Memento Mori Collection for Men', 'David Yurman, Memento Mori, skull amulet, mortality reflection, Medieval tradition, live life fully.', 'Discover our captivating Memento Mori Skull Amulet, echoing the Medieval tradition of contemplating mortality. Embrace life\'s richness with this powerful symbol.', '2024-03-10 14:32:49'),
(23, 19, 'Box Chain Necklace', 'Men', 'box chain necklace', 'DAVID YURMAN', 5, 'David Yurman chains are inspired by classical and original motifs, and are meticulously crafted by artisans. Each is designed to be worn alone, layered, or complemented with unique pendants or amulets from our other collections.', 'Details :\r\nSterling silver\r\nChain, 4.8mm\r\nLobster clasp\r\nStyle #CH0235MSS\r\n\r\nMetal Care :\r\nUse the white side of the provided David Yurman polishing cloth to gently wipe clean, then remove any remaining tarnish with mild diluted soap. Rinse with warm water and dry thoroughly before storing the design in its jewelry pouch.', 470, 390, '1710081598_1.webp', '1710081581_2.webp', '1710081581_3.webp', 35, 0, 1, 'Chain Collection for Men', 'David Yurman, box chain necklace, artisan craftsmanship, classical motifs, original designs, versatile jewelry, pendant accessories.', 'Discover David Yurman\'s exquisite box chain necklaces, meticulously crafted by artisans and inspired by classical and original motifs. Versatile and timeless, each piece can be worn alone or layered, adorned with unique pendants from our collections.', '2024-03-10 14:39:41'),
(24, 19, 'Pearl Multi Row Chain Necklace', 'Women', 'dy madison® collection for women', 'DAVID YURMAN', 5, 'An elegant take on the classic chain, enhanced by the luster and beauty of pearls.', 'Details :\r\n18-karat yellow gold\r\nCultured freshwater pearls, 7-10.5mm\r\nTotal length, 19.5in\r\nToggle clasp\r\nStyle #N17771 88BPE195\r\nUPC 192740753862\r\n\r\nMetal Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch. Do not use abrasive cleaners, steamers or ultrasonic machines.\r\n\r\nGemstone Care :\r\nAvoid contact with perfumes, hairsprays or other chemicals. Clean with a moistened cloth. Do not use chemical jewelry cleaners.', 750, 599.99, '1710082021_1.webp', '1710082001_2.webp', '1710082001_3.webp', 10, 0, 1, 'DY Madison® Collection for Women', 'David yurman, dy madison collection, women\'s jewelry, classic chain, pearls, elegance, timeless beauty', 'Explore the DY Madison® collection for women, featuring an elegant interpretation of the classic chain adorned with the timeless beauty of pearls.', '2024-03-10 14:46:41'),
(25, 19, 'Helena Tassel Necklace', 'Women', 'helena tassel necklace', 'DAVID YURMAN', 5, 'In the Helena Collection, David Yurman returns to the longer, leaner twist of his first handmade Cable bracelet, wrapping the iconic form with 18K yellow gold threads accented with hand-set pavé diamonds.', 'Details :\r\n18-karat yellow gold\r\nPavé-set diamonds, 0.61 total carat weight\r\nAdjustable length, 30in\r\nTassel, 2.5in\r\nChain, 2.7mm\r\nSlider clasp\r\nStyle #N16123D88ADI\r\nUPC 192740943195\r\n\r\nMetal Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch. Do not use abrasive cleaners, steamers or ultrasonic machines.\r\nGemstone Care\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch.', 800, 480, '1710082463_1.webp', '1710082449_2.webp', '1710082449_3.webp', 15, 0, 1, 'Helena Collection for Women', 'David Yurman, Helena collection, david yurman, tassel necklace, 18k yellow gold, pavé diamonds, refined craftsmanship.', 'Discover the elegance of the Helena tassel necklace from David Yurman, echoing the refined craftsmanship of the Helena Collection. Adorned with 18K yellow gold threads and hand-set pavé diamonds, it embodies timeless luxury.', '2024-03-10 14:54:09'),
(26, 19, 'Forged Carbon Band Ring', 'Men', 'forged carbon band ring', 'DAVID YURMAN', 4, 'Forged carbon is a lightweight yet strong composite originally used in aeronautics and sports cars. For jewelry, David Yurman pioneered a technique which fuses the modern material and precious metal into innovative, graphic designs.', 'Details :\r\n18-karat yellow gold\r\nForged carbon\r\nRing, 6mm\r\nStyle #R25022M88BFG\r\n\r\nMetal Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch. Do not use abrasive cleaners, steamers or ultrasonic machines.', 439.99, 390.99, '1710172629_1.webp', '1710172611_2.webp', '1710172611_3.webp', 30, 0, 1, 'Forged Carbon Collection for Men', 'Forged Carbon, Carbon Ring, Band Ring, David Yurman Jewelry, Lightweight Jewelry, Strong Composite, Modern Jewelry, Innovative Design, Graphic Jewelry, Precious Metal, Aeronautics Material, Sports Cars Material', 'Forged carbon is a lightweight yet strong composite originally used in aeronautics and sports cars. David Yurman pioneers a technique fusing this modern material with precious metals, creating innovative and graphic jewelry designs.', '2024-03-11 15:56:51'),
(27, 19, 'Streamline® Two Row Band Ring', 'Men', 'streamline® two row band ring', 'DAVID YURMAN', 5, 'Inspired by clean lines and smooth metal surfaces, these minimalist designs are sculpted with engineered precision. Every pavé diamond or colored gemstone is carefully matched for color and hand set—a tribute to DY artistry.', 'Inspired by clean lines and smooth metal surfaces, these minimalist designs are sculpted with engineered precision. Every pavé diamond or colored gemstone is carefully matched for color and hand set—a tribute to DY artistry.', 339.99, 299.99, '1710172946_1.webp', '1710172929_2.webp', '1710172929_3.webp', 10, 0, 1, 'Streamline® Collection for Men', 'DAVID YURMAN, clean lines, smooth metal surfaces, minimalist designs, engineered precision, pavé diamond, colored gemstone, dy artistry.', 'inspired by clean lines and smooth metal surfaces, these minimalist designs are sculpted with engineered precision. every pavé diamond or colored gemstone is carefully matched for color and hand set—a tribute to dy artistry.', '2024-03-11 16:02:09'),
(28, 19, 'Pavéflex Band Ring', 'Women', 'paveflex band ring', 'DAVID YURMAN', 4.5, 'Through innovative engineering, this Pavéflex® design twists and moves with ease while never forgetting its elegant form. An opening in the back allows it to expand to fit a range of sizes.', 'Details :\r\n18-karat yellow gold\r\nPavé-set diamonds, 1.17 total carat weight\r\nRing, 5mm\r\nFlexible design\r\nStyle #R13529D88ADI\r\n\r\nMetal Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch. Do not use abrasive cleaners, steamers or ultrasonic machines.\r\n\r\nGemstone Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch.', 699.99, 449.99, '1710173275_1.webp', '1710173257_2.webp', '1710173257_3.webp', 15, 0, 1, 'Pavéflex Collection for Women', 'pavéflex band ring, flexible ring, gemstone ring, shimmering ring, jewelry design', 'This ring is characterized by its flexibility and the meticulous arrangement of small gemstones across its surface, creating a shimmering effect that catches the eye.', '2024-03-11 16:07:37'),
(29, 19, 'Sculpted Cable Band Ring', 'Women', 'sculpted cable band ring', 'DAVID YURMAN', 5, 'In Sculpted Cable, David Yurman transforms his signature design motif into a carved form. The effect is an entrancing wavelike pattern that retains the dimensional look of Cable’s original helix.', 'Details :\r\n18-karat yellow gold\r\nPavé-set-set diamonds, 0.39 total carat weight\r\nRing, 4.6mm\r\nStyle #R18185D88ADI\r\n\r\nMetal Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch. Do not use abrasive cleaners, steamers or ultrasonic machines.\r\n\r\nGemstone Care :\r\nUse a soft cloth to gently wipe clean, then remove any remaining impurities with mild diluted soap. Rinse with warm water and dry thoroughly before storing in the provided jewelry pouch.', 700, 579.99, '1710173701_1.webp', '1710173685_2.png', '1710173685_3.webp', 15, 0, 1, 'Sculpted Cable Collection for Women', 'David yurman, sculpted cable band ring, cable motif ring, elegant ring, sophisticated jewelry', 'Crafted with intricate cable motifs and sculpted details, this band ring embodies timeless elegance and sophistication.', '2024-03-11 16:14:45'),
(30, 13, 'Embroidered Dress', 'Select Pro', 'embroidered-dress', 'H&M', 4.5, 'Limited Edition. Sleeveless, empire-waist dress in satin decorated with floral embroidery. Square neckline, buttons at back, and a voluminous skirt with outer layer in tulle. Liner skirt in stiff tulle for added volume. Lined.', 'Length: Knee-length\r\nSleeve Length: Sleeveless\r\nFit: Regular fit\r\nNeckline: Square Neckline\r\nDescription: White, Floral\r\nImported: Yes\r\nCollection: H&M Limited Edition\r\n\r\nComposition\r\nShell:Polyester 100%\r\nLining:Polyester 100%\r\nAdditional material information\r\nThe total weight of this product contains:\r\n\r\n100% Recycled polyester\r\nWe exclude the weight of minor components such as, but not exclusively: threads, buttons, zippers, embellishments and prints.\r\n\r\nThe total weight of the product is calculated by adding the weight of all layers and main components together. Based on that, we calculate how much of that weight is made out by each material. For sets and multipacks, all pieces are counted together as one product in calculations.\r\n\r\nMaterial: Satin, Tulle\r\nMaterials in this product explained\r\nPolyester\r\nPolyester is a synthetic fiber made from crude oil (a fossil resource).\r\nRecycled polyester\r\nRecycled polyester is polyester made from PET bottles or end-of-life textile waste. The PET bottles or textile waste is mechanically recycled and processed into new yarn.\r\n\r\nCare guide\r\nYou too can help the environment and make fashion more sustainable. Bring unwanted clothes or home textiles to any H&M store and they will be reworn, reused or recycled.\r\n\r\nRead about how you can make your clothes last longer\r\nCare instructions\r\nOnly non-chlorine bleach when needed\r\nNo dry clean\r\nMedium iron\r\nMachine wash cool\r\nLine dry', 59.99, 39.98, '1710765873_1.jpeg', '1710765859_2.webp', '1710765859_3.webp', 15, 0, 1, 'H&M Kids Limited Edition', 'H&M Kids, Limited Collection, Sleeveless Dress, Empire Waist, Floral Embroidery, Square Neckline, Button Closure, Voluminous Skirt, Tulle Layering, Special Occasion Wear, Children\'s Fashion, Kids Clothing.', 'Discover the elegance of H&M Kids Limited Collection. Shop our sleeveless empire-waist dress crafted in satin with exquisite floral embroidery. Featuring a square neckline, button closure at the back, and a voluminous skirt layered with tulle. Perfect for your little one\'s special occasions.', '2024-03-18 12:44:19'),
(31, 13, 'Ruffle-trimmed Sweatshirt Cardigan', 'Women', 'ruffle-trimmed-sweatshirt-cardigan', 'H&M', 4.5, 'Cardigan in lightweight sweatshirt fabric. Round neckline, snap fasteners at front, dropped shoulders, and long sleeves. Scalloped-edge ruffle trim in woven cotton fabric with eyelet embroidery extending over shoulders. Ribbing at neckline, placket, cuffs, and hem.', 'Length: Regular length\r\nSleeve Length: Long sleeve\r\nFit: Regular fit\r\nNeckline: Round Neck\r\nDescription: Light dusty pink, Solid-color\r\nImported: Yes\r\n\r\nComposition\r\nShell:Cotton 80%, Polyester 20%\r\nFrill:Cotton 100%\r\nMaterial: French Terry\r\nMaterials in this product explained\r\nCotton\r\nCotton is a soft and versatile natural fiber harvested from the cotton plant.\r\nPolyester\r\nPolyester is a synthetic fiber made from crude oil (a fossil resource).\r\n\r\nYou too can help the environment and make fashion more sustainable. Bring unwanted clothes or home textiles to any H&M store and they will be reworn, reused or recycled.\r\n\r\nCare instructions :\r\n\r\nTumble dry medium\r\nOnly non-chlorine bleach when needed\r\nNo dry clean\r\nMedium iron\r\nMachine wash cool', 30, 14.99, '1710768514_1.webp', '1710768499_2.webp', '1710768499_3.webp', 20, 0, 1, 'H&M Kids Limited Edition', 'Cardigan, sweatshirt, lightweight, round neckline, snap fasteners, dropped shoulders, long sleeves, ruffle trim, woven cotton, eyelet embroidery, scalloped edge, ribbing, fashion, clothing, women\'s wear, casual wear, stylish, comfortable, trendy, fall fashion.', 'Lightweight sweatshirt fabric cardigan featuring a round neckline, snap fasteners at the front, dropped shoulders, and long sleeves. Adorned with scalloped-edge ruffle trim made of woven cotton fabric with eyelet embroidery extending over the shoulders. Includes ribbing at neckline, placket, cuffs, and hem.', '2024-03-18 13:28:19'),
(32, 1, ' NIRVANA ® TANK TOP', 'Men', 'nirvana-tank-top', 'ZARA', 4, 'Round neck T-shirt with short sleeves. Nirvana ® print at chest and back.', 'The NIRVANA ® Tank Top offers both style and comfort. Crafted with a round neck and short sleeves, this T-shirt is designed for everyday wear. Made from premium quality fabric, it ensures a comfortable fit and durability. The iconic Nirvana ® print at the chest and back adds a touch of rock-inspired flair to your look. Available in a range of sizes, this tank top is suitable for both men and women. Pair it with your favorite jeans or shorts for a casual yet trendy ensemble. Easy to care for, simply machine wash cold and tumble dry low for long-lasting wear.', 28.99, 17.9, '1710769118_1.jpg', '1710769208_2.jpg', '1710769208_3.jpg', 15, 0, 1, 'ZARA Kids', 'NIRVANA ®, tank top, T-shirt, round neck, short sleeves, casual wear, comfort, style, iconic print, men\'s fashion, women\'s fashion.', 'Elevate your casual style with the NIRVANA ® Tank Top. Featuring a round neck, short sleeves, and iconic Nirvana ® print, this comfortable yet stylish T-shirt is perfect for everyday wear.', '2024-03-18 13:38:23'),
(33, 15, 'Kids Twill Easy Shorts', 'Men', 'kids-twill-easy-shorts', 'GAP', 5, 'Soft, stretch cotton twill shorts with elasticized waist, drawcords, and faux zipper. Front and back pockets for added convenience.', 'FIT & SIZING :\r\nEasy pull-on waist.\r\nEasy through the hip and thigh.\r\nHits at the knee.\r\n\r\nFABRIC & CARE :\r\n98% Cotton, 2% Spandex.\r\nMachine wash.\r\nImported.', 41.95, 29.95, '1710926776_1.avif', '1710926776_2.avif', '1710926736_3.avif', 15, 0, 1, 'GAP Kids', 'Kids Twill Easy Shorts, GAP, children\'s clothing, cotton twill shorts, elasticized waist, drawcords, pockets, comfortable, durable, everyday wear.', 'Discover comfortable and stylish Kids Twill Easy Shorts for just $29.95. Crafted from soft cotton twill with an elasticized waist and convenient pockets. Shop now for durable, everyday wear!', '2024-03-20 09:25:36');

